WITH cleaned AS (SELECT id, method, amount, CASE WHEN status IN ('FAILED', 'REFUNDED') THEN 'Priority' ELSE 'Other' END AS status_group, COALESCE(method, 'NONE') AS method_clean FROM payments WHERE paid_at > TO_DATE('2023-08-18')) SELECT *, LEAD(amount, 2) OVER (PARTITION BY method ORDER BY amount, id) AS next_amount, SUM(amount) OVER (PARTITION BY method ORDER BY amount, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_amount, ROW_NUMBER() OVER (PARTITION BY method ORDER BY amount DESC, id) AS seq_no, LEAD(amount, 2) OVER (PARTITION BY method ORDER BY amount, id) AS next_amount_2 FROM cleaned;
